#include "lms/Database.h"
#include "lms/LatePenalty.h"
#include "lms/User.h"
#include "lms/Utilities.h"
#include <ctime>
#include <iomanip>
#include <iostream>
#include <memory>
#include <sstream>
#include <stdexcept>
#include <string>

using namespace lms;
namespace {
class Repository {
    Database db_;
public:
    Repository():db_(std::string("lms.db")){db_.exec("PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','lecturer','hod','student')),department_id INTEGER REFERENCES departments(id)); CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,department_id INTEGER NOT NULL REFERENCES departments(id),lecturer_id INTEGER REFERENCES users(id)); CREATE TABLE IF NOT EXISTS enrolments(student_id INTEGER NOT NULL REFERENCES users(id),course_id INTEGER NOT NULL REFERENCES courses(id),PRIMARY KEY(student_id,course_id)); CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY,course_id INTEGER NOT NULL REFERENCES courses(id),title TEXT NOT NULL,deadline TEXT NOT NULL,max_mark REAL NOT NULL CHECK(max_mark>0)); CREATE TABLE IF NOT EXISTS extensions(assignment_id INTEGER NOT NULL REFERENCES assignments(id),student_id INTEGER NOT NULL REFERENCES users(id),deadline TEXT NOT NULL,PRIMARY KEY(assignment_id,student_id)); CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY,assignment_id INTEGER NOT NULL REFERENCES assignments(id),student_id INTEGER NOT NULL REFERENCES users(id),submitted_at TEXT NOT NULL,work TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('submitted','late','marked','moderated','released')),mark REAL,feedback TEXT NOT NULL DEFAULT '',late_days INTEGER NOT NULL DEFAULT 0,UNIQUE(assignment_id,student_id)); CREATE TABLE IF NOT EXISTS mark_audit(id INTEGER PRIMARY KEY,submission_id INTEGER NOT NULL REFERENCES submissions(id),actor_id INTEGER NOT NULL REFERENCES users(id),changed_at TEXT NOT NULL,old_mark REAL,new_mark REAL,reason TEXT NOT NULL);"); seedAdmin();}
    sqlite3* db(){return db_.get();}
    void seedAdmin(){Statement q(db(),"SELECT COUNT(*) FROM users WHERE role='admin'");q.row();if(q.num(0)==0){auto s=generateSalt();Statement i(db(),"INSERT INTO users(username,salt,password_hash,role) VALUES(?,?,?,'admin')");i.text(1,"admin");i.text(2,s);i.text(3,hashPassword("Admin123!",s));i.done();}}
    std::unique_ptr<User> login(){for(int tries=0;tries<3;++tries){auto u=readInput("Username: "),p=readInput("Password: ");Statement q(db(),"SELECT id,username,role,COALESCE((SELECT name FROM departments WHERE id=department_id),'') FROM users WHERE username=? AND salt IS NOT NULL");q.text(1,u);if(q.row()){auto saltVal=[&](){Statement x(db(),"SELECT salt,password_hash FROM users WHERE username=?");x.text(1,u);x.row();return std::pair<std::string,std::string>{x.str(0),x.str(1)};}();if(hashPassword(p,saltVal.first)==saltVal.second)return UserFactory::make({q.num(0),q.str(1),q.str(2),q.str(3)});}std::cout<<"Invalid credentials.\n";}return {};}
    void addUser(const Account& actor){std::string r=readInput("Role (student/lecturer/hod): ");if(r!="student"&&r!="lecturer"&&r!="hod"){std::cout<<"Invalid role.\n";return;}auto u=readInput("Username: "),p=readInput("Initial password (min 8 chars): ");if(u.empty()||p.size()<8)throw std::runtime_error("Username required and password must be at least 8 characters");int d=readNumber("Department ID: ");auto s=generateSalt();Statement i(db(),"INSERT INTO users(username,salt,password_hash,role,department_id) VALUES(?,?,?,?,?)");i.text(1,u);i.text(2,s);i.text(3,hashPassword(p,s));i.text(4,r);i.integer(5,d);i.done();std::cout<<"Account created.\n";(void)actor;}
    void addDepartment(){auto n=readInput("Department name: ");Statement i(db(),"INSERT INTO departments(name) VALUES(?)");i.text(1,n);i.done();std::cout<<"Department created.\n";}
    void addCourse(){auto c=readInput("Course code: "),n=readInput("Course name: ");int d=readNumber("Department ID: "),l=readNumber("Lecturer user ID: ");Statement i(db(),"INSERT INTO courses(code,name,department_id,lecturer_id) VALUES(?,?,?,?)");i.text(1,c);i.text(2,n);i.integer(3,d);i.integer(4,l);i.done();std::cout<<"Course created.\n";}
    void enrol(){int s=readNumber("Student user ID: "),c=readNumber("Course ID: ");Statement i(db(),"INSERT INTO enrolments(student_id,course_id) SELECT ?,? WHERE EXISTS(SELECT 1 FROM users WHERE id=? AND role='student')");i.integer(1,s);i.integer(2,c);i.integer(3,s);i.done();std::cout<<"Enrolment recorded (verify student/course IDs).\n";}
    void createAssignment(const Account&a){int c=readNumber("Course ID: ");Statement own(db(),"SELECT id FROM courses WHERE id=? AND lecturer_id=?");own.integer(1,c);own.integer(2,a.id);if(!own.row()){std::cout<<"You are not assigned to that course.\n";return;}auto t=readInput("Title: "),d=readInput("Deadline (YYYY-MM-DD HH:MM:SS UTC): ");double m=readScore("Maximum mark: ",1000000);Statement i(db(),"INSERT INTO assignments(course_id,title,deadline,max_mark) VALUES(?,?,?,?)");i.integer(1,c);i.text(2,t);i.text(3,d);i.real(4,m);i.done();std::cout<<"Assignment created.\n";}
    void submit(const Account&a){int id=readNumber("Assignment ID: ");Statement info(db(),"SELECT a.deadline,a.max_mark,COALESCE(e.deadline,a.deadline),s.id,s.status FROM assignments a JOIN enrolments n ON n.course_id=a.course_id AND n.student_id=? LEFT JOIN extensions e ON e.assignment_id=a.id AND e.student_id=? LEFT JOIN submissions s ON s.assignment_id=a.id AND s.student_id=? WHERE a.id=?");info.integer(1,a.id);info.integer(2,a.id);info.integer(3,a.id);info.integer(4,id);if(!info.row()){std::cout<<"Assignment not found or you are not enrolled.\n";return;}auto effective=info.str(2);int old=info.num(3);std::string status=info.str(4);if(old&&status!="submitted"&&status!="late"){std::cout<<"This submission can no longer be changed.\n";return;}auto text=readInput("Submission text/path: ");if(text.empty())throw std::runtime_error("Submission cannot be empty");auto t=currentUtcTime();if(old && t>effective){std::cout<<"Resubmission is allowed only before the effective deadline.\n";return;}int days=0;if(t>effective){ // Dates use sortable UTC ISO-8601 form; calculate late calendar days by timestamp differences.
 std::tm tm{};std::istringstream ss(effective);ss>>std::get_time(&tm,"%Y-%m-%d %H:%M:%S");auto deadline= timegm(&tm);std::tm nowtm{};std::istringstream ns(t);ns>>std::get_time(&nowtm,"%Y-%m-%d %H:%M:%S");auto seconds=timegm(&nowtm)-deadline;days=static_cast<int>((seconds+86399)/86400);}
 std::string st=days>0?"late":"submitted";if(old){Statement up(db(),"UPDATE submissions SET submitted_at=?,work=?,status=?,mark=NULL,feedback='',late_days=? WHERE id=?");up.text(1,t);up.text(2,text);up.text(3,st);up.integer(4,days);up.integer(5,old);up.done();}else{Statement i(db(),"INSERT INTO submissions(assignment_id,student_id,submitted_at,work,status,late_days) VALUES(?,?,?,?,?,?)");i.integer(1,id);i.integer(2,a.id);i.text(3,t);i.text(4,text);i.text(5,st);i.integer(6,days);i.done();}std::cout<<"Submission saved as "<<st<<".\n";}
    void extend(const Account&a){int as=readNumber("Assignment ID: "),student=readNumber("Student user ID: ");Statement own(db(),"SELECT a.id FROM assignments a JOIN courses c ON c.id=a.course_id WHERE a.id=? AND c.lecturer_id=?");own.integer(1,as);own.integer(2,a.id);if(!own.row())throw std::runtime_error("Assignment is not in your course");auto d=readInput("New individual deadline (YYYY-MM-DD HH:MM:SS UTC): ");Statement i(db(),"INSERT INTO extensions(assignment_id,student_id,deadline) VALUES(?,?,?) ON CONFLICT(assignment_id,student_id) DO UPDATE SET deadline=excluded.deadline");i.integer(1,as);i.integer(2,student);i.text(3,d);i.done();std::cout<<"Extension recorded.\n";}
    void mark(const Account&a){int id=readNumber("Submission ID: ");Statement q(db(),"SELECT s.mark,a.max_mark,s.late_days,c.lecturer_id FROM submissions s JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id WHERE s.id=?");q.integer(1,id);if(!q.row()||q.num(3)!=a.id)throw std::runtime_error("Submission not found in your course");double max=q.decimal(1);double raw=readScore("Raw mark: ",max);auto feedback=readInput("Written feedback: ");auto reason=readInput("Reason for mark (required for audit): ");if(reason.empty())throw std::runtime_error("Audit reason is required");SchoolLatePenalty penalty;double final=penalty.apply(raw,max,q.num(2));double prev=q.decimal(0);Statement u(db(),"UPDATE submissions SET mark=?,feedback=?,status='marked' WHERE id=?");u.real(1,final);u.text(2,feedback);u.integer(3,id);u.done();Statement au(db(),"INSERT INTO mark_audit(submission_id,actor_id,changed_at,old_mark,new_mark,reason) VALUES(?,?,?,?,?,?)");au.integer(1,id);au.integer(2,a.id);au.text(3,currentUtcTime());// First mark is recorded with old value zero.
 au.real(4,prev);au.real(5,final);au.text(6,reason);au.done();std::cout<<"Saved final mark "<<final<<" (late policy applied).\n";}
    void moderate(const Account&a){int id=readNumber("Submission ID: ");Statement q(db(),"SELECT s.mark,s.status,c.department_id FROM submissions s JOIN assignments x ON x.id=s.assignment_id JOIN courses c ON c.id=x.course_id WHERE s.id=?");q.integer(1,id);if(!q.row()||q.str(1)!="marked")throw std::runtime_error("Submission must be marked before moderation");int dept=q.num(2);Statement dh(db(),"SELECT department_id FROM users WHERE id=?");dh.integer(1,a.id);if(dh.row()&&dh.num(0)!=dept)throw std::runtime_error("Submission is outside your department");std::cout<<"Proposed mark: "<<q.decimal(0)<<"\n";if(readInput("Approve moderation? (y/n): ")!="y")return;Statement u(db(),"UPDATE submissions SET status='moderated' WHERE id=?");u.integer(1,id);u.done();std::cout<<"Moderated.\n";}
    void release(const Account&a){int id=readNumber("Submission ID to release: ");Statement q(db(),"SELECT c.department_id,s.status FROM submissions s JOIN assignments x ON x.id=s.assignment_id JOIN courses c ON c.id=x.course_id WHERE s.id=?");q.integer(1,id);if(!q.row()||q.str(1)!="moderated")throw std::runtime_error("Only moderated marks can be released");Statement dh(db(),"SELECT department_id FROM users WHERE id=?");dh.integer(1,a.id);if(dh.row()&&dh.num(0)!=q.num(0))throw std::runtime_error("Submission is outside your department");Statement u(db(),"UPDATE submissions SET status='released' WHERE id=?");u.integer(1,id);u.done();std::cout<<"Mark released to student.\n";}
    void assignments(const Account&a){Statement q(db(),"SELECT a.id,a.title,a.deadline,a.max_mark,COALESCE(e.deadline,a.deadline) FROM assignments a JOIN enrolments n ON n.course_id=a.course_id LEFT JOIN extensions e ON e.assignment_id=a.id AND e.student_id=n.student_id WHERE n.student_id=?");q.integer(1,a.id);while(q.row())std::cout<<"#"<<q.num(0)<<" "<<q.str(1)<<" | deadline "<<q.str(4)<<" | max "<<q.decimal(3)<<"\n";}
    void studentMarks(const Account&a){Statement q(db(),"SELECT a.title,s.mark,s.feedback,s.status FROM submissions s JOIN assignments a ON a.id=s.assignment_id WHERE s.student_id=? AND s.status='released'");q.integer(1,a.id);while(q.row())std::cout<<q.str(0)<<" | mark "<<q.decimal(1)<<" | "<<q.str(2)<<"\n";}
};
Repository* repo=nullptr;

}
namespace lms {
void AdminUser::menu(){for(;;){std::cout<<"\nAdmin: 1 Create account 2 Create department 3 Create course 4 Enrol student 0 Logout\n";int x=readNumber("> ",0,4);if(x==0)return;try{if(x==1)repo->addUser(account_);else if(x==2)repo->addDepartment();else if(x==3)repo->addCourse();else if(x==4)repo->enrol();}catch(const std::exception&e){std::cout<<"Operation failed: "<<e.what()<<"\n";}}}
void LecturerUser::menu(){for(;;){std::cout<<"\nLecturer: 1 Create assignment 2 Grant individual extension 3 List submissions 4 Mark submission 0 Logout\n";int x=readNumber("> ",0,4);if(!x)return;try{if(x==1)repo->createAssignment(account_);else if(x==2)repo->extend(account_);else if(x==3){Statement q(repo->db(),"SELECT s.id,a.title,u.username,s.status,s.submitted_at FROM submissions s JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id JOIN users u ON u.id=s.student_id WHERE c.lecturer_id=?");q.integer(1,account_.id);while(q.row())std::cout<<"#"<<q.num(0)<<" | "<<q.str(1)<<" | "<<q.str(2)<<" | "<<q.str(3)<<" | "<<q.str(4)<<"\n";}else repo->mark(account_);}catch(const std::exception&e){std::cout<<"Operation failed: "<<e.what()<<"\n";}}}
void HodUser::menu(){for(;;){std::cout<<"\nHoD: 1 View marked submissions 2 Moderate 3 Release approved mark 0 Logout\n";int x=readNumber("> ",0,3);if(!x)return;try{if(x==1){Statement q(repo->db(),"SELECT s.id,a.title,u.username,s.mark,s.status FROM submissions s JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id JOIN users u ON u.id=s.student_id WHERE s.status IN ('marked','moderated') AND c.department_id=(SELECT department_id FROM users WHERE id=?)");q.integer(1,account_.id);while(q.row())std::cout<<"#"<<q.num(0)<<" | "<<q.str(1)<<" | "<<q.str(2)<<" | "<<q.decimal(3)<<" | "<<q.str(4)<<"\n";}else if(x==2)repo->moderate(account_);else repo->release(account_);}catch(const std::exception&e){std::cout<<"Operation failed: "<<e.what()<<"\n";}}}
void StudentUser::menu(){for(;;){std::cout<<"\nStudent: 1 View assignment list 2 Submit/resubmit 3 View released marks/feedback 0 Logout\n";int x=readNumber("> ",0,3);if(!x)return;try{if(x==1)repo->assignments(account_);else if(x==2)repo->submit(account_);else repo->studentMarks(account_);}catch(const std::exception&e){std::cout<<"Operation failed: "<<e.what()<<"\n";}}}
}

int main(){try{Repository r;repo=&r;std::cout<<"Moderated LMS (SQLite)\nInitial administrator: admin / Admin123! — change this password before deployment.\n";for(;;){std::cout<<"\n1 Login 0 Exit\n";int x=readNumber("> ",0,1);if(!x)break;try{auto u=r.login();if(u){std::cout<<"Welcome, "<<u->account().username<<" ("<<roleName(u->role())<<")\n";u->menu();}}catch(const std::exception&e){std::cout<<"Error: "<<e.what()<<"\n";}}}catch(const std::exception&e){std::cerr<<"Fatal startup error: "<<e.what()<<"\n";return 1;}return 0;}
